    Differential Revision: https://phabricator.services.mozilla.com/D244092

diff --git a/mailnews/local/src/StoreIndexer.cpp b/mailnews/local/src/StoreIndexer.cpp
index c440a79c1c4..b5647e13748 100644
--- a/mailnews/local/src/StoreIndexer.cpp
+++ b/mailnews/local/src/StoreIndexer.cpp
@@ -177,8 +177,8 @@ NS_IMETHODIMP StoreIndexer::OnDataAvailable(nsIRequest* req,

       if (!mIsStupidlyLongLine) {
         MOZ_ASSERT(!incompleteLine);
-        // Ignore result of ParseFolderLine(). Better to just keep going.
-        mParser->ParseFolderLine(line.Elements(), line.Length());
+        // Ignore result of ParseAFolderLine(). Better to just keep going.
+        mParser->ParseAFolderLine(line.Elements(), line.Length());
       } else if (!incompleteLine) {
         // Soaked up entire stupidly-long-line, stop discarding data.
         mIsStupidlyLongLine = false;
diff --git a/mailnews/local/src/nsParseMailbox.h b/mailnews/local/src/nsParseMailbox.h
index 786d8568aa7..eec01770930 100644
--- a/mailnews/local/src/nsParseMailbox.h
+++ b/mailnews/local/src/nsParseMailbox.h
@@ -47,11 +47,6 @@ class nsParseMailMessageState : public nsIMsgParseMailMsgState,

   nsParseMailMessageState();

-  nsresult ParseFolderLine(const char* line, uint32_t lineLength);
-  nsresult ParseHeaders();
-  nsresult FinalizeHeaders();
-  nsresult InternSubject(HeaderData* header);
-
   // A way to pass in 'out-of-band' envelope sender/timestamp data.
   // Totally optional, but envDate is used to fill in on malformed messages
   // without a "Date:" header.
@@ -68,6 +63,11 @@ class nsParseMailMessageState : public nsIMsgParseMailMsgState,
   uint16_t m_body_lines;

  protected:
+  nsresult ParseFolderLine(const char* line, uint32_t lineLength);
+  nsresult ParseHeaders();
+  nsresult FinalizeHeaders();
+  nsresult InternSubject(HeaderData* header);
+
   nsMailboxParseState m_state;
   nsCOMPtr<nsIMsgDBHdr> m_newMsgHdr; /* current message header we're building */
   // These two aren't part of the message, but may be provided 'out-of-band',
@@ -120,7 +120,6 @@ class nsParseMailMessageState : public nsIMsgParseMailMsgState,
   nsTArray<nsCString> m_customDBHeaders;
   nsTArray<HeaderData> m_customDBHeaderData;
   nsCString m_receivedValue;  // accumulated received header
- protected:
   virtual ~nsParseMailMessageState() {};
 };
